import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`therapy-documentation`,heroTitle:`Turn appointments, intake notes, and follow-ups into organized practice documentation`,heroSubtitle:`Perplexity Computer turns session context into structured therapy documentation with summaries, interventions, follow-ups, and review flags.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload notes`,inputFileAccept:`.pdf,.doc,.docx,.txt,.csv,.xlsx,.xls`,inputFilePrefill:`Use the uploaded session context to draft therapy documentation for human review. 1) Identify the session date, client context, goals, topics discussed, interventions, client response, risk indicators, homework, and follow-up needs. 2) Organize the note into a concise clinical structure without adding unsupported details. 3) Flag ambiguous, sensitive, or missing information that requires clinician confirmation. 4) Draft a follow-up checklist and next-session agenda. 5) Deliver a polished draft note that is ready to review and edit.`,heroOverlaySteps:[`Reading session context, goals, topics, interventions, and follow-ups`,`Organizing the material into concise documentation sections`,`Flagging ambiguous, sensitive, or missing details for clinician review`,`Draft note, follow-up checklist, and next-session agenda ready`],generatingSteps:[`Reading the uploaded session context and documentation requirements`,`Designing an agent to structure notes, interventions, and follow-ups`,`Configuring review flags for ambiguous, sensitive, or missing information`,`Packaging the draft note, checklist, and next-session agenda`],featureSectionTitle:`From session context to review-ready documentation`,featureCardTitles:[`Connects to your documentation workflow`,`Outputs you can review`],featureCardDescriptions:[`Computer separates documentation into context extraction, clinical structuring, review flags, and follow-up planning, then routes each step to the right model.`,`Uploads, Docs, Sheets, Notion, and task tools can feed one workflow so notes and follow-ups stay organized.`,`Structured draft notes. Intervention summaries. Review flags. Follow-up checklists. Computer prepares documentation so you can focus on clinical judgment.`],capabilitySectionTitle:`Your documentation assistant, on demand`,capabilitySectionSubtitle:`Upload session context, step away, and come back to a structured note ready to review.`,capabilityCards:[{title:`Session Summaries`,description:`Computer can summarize goals, themes, interventions, client response, and follow-up needs in a clear documentation format.`},{title:`Structured Notes`,description:`Computer can organize drafts into concise sections that are easier for clinicians to review, edit, and finalize.`},{title:`Review Flags`,description:`Computer can flag ambiguous, sensitive, or missing details so a clinician can confirm them before documentation is finalized.`},{title:`Connect Your Tools`,description:`Computer can organize drafts and follow-ups across uploads, Docs, Notion, Sheets, and task tools.`},{title:`Remember Your Format`,description:`Computer can remember preferred note sections, tone, and recurring follow-up patterns for future drafts.`},{title:`Follow-Up Planning`,description:`Computer can turn homework, open questions, and next-session topics into a checklist for review.`}]});export{t as default};
